void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;
    rephase_limit += 1024;

    // Adjust phases based on recent activity
    for (int i = 1; i <= vars; i++) {
        if (activity[i] > 1e-10) {
            // Favor phases that have been successful recently
            if (rand() % 100 < 70) {
                saved[i] = local_best[i];
            } else if (rand() % 100 < 15) {
                saved[i] = -local_best[i];
            } else if (rand() % 100 < 10) {
                saved[i] = rand() % 2 ? 1 : -1;
            } else {
                saved[i] = 0;
            }
        }
    }
}
